package de.schaepi.puls180;
import android.app.*;import android.content.*;import android.text.InputType;import android.widget.*;import java.time.*;import java.time.format.*;import java.util.*;import org.json.*;
public final class UserProfile{
 private UserProfile(){}
 private static android.content.SharedPreferences control(Context c){return c.getSharedPreferences("userProfileControl",0);}
 private static int active(Context c){return Math.max(1,Math.min(2,control(c).getInt("active",1)));}
 private static android.content.SharedPreferences slot(Context c,int n){return c.getSharedPreferences("userProfile"+n,0);}
 private static android.content.SharedPreferences p(Context c){return slot(c,active(c));}
 private static android.content.SharedPreferences owners(Context c){return c.getSharedPreferences("measurementOwners",0);}
 public static String slotName(Context c,int n){String name=slot(c,n).getString("name","").trim();return name.isEmpty()?"Benutzer "+n:name;}
 public static int activeSlot(Context c){return active(c);}
 public static String activeLabel(Context c){return slotName(c,active(c));}
 public static String name(Context c){return p(c).getString("name","");}
 public static org.json.JSONObject transferData(Context c)throws org.json.JSONException{android.content.SharedPreferences prefs=p(c);org.json.JSONObject data=new org.json.JSONObject();String h=prefs.getString("height",""),w=prefs.getString("weight",""),date=prefs.getString("weightDate","");data.put("heightCm",h.isEmpty()?org.json.JSONObject.NULL:Integer.valueOf(h));data.put("weightKg",w.isEmpty()?org.json.JSONObject.NULL:Double.valueOf(w.replace(',','.')));data.put("weightDate",w.isEmpty()||date.isEmpty()?org.json.JSONObject.NULL:date);org.json.JSONArray source=new org.json.JSONArray(prefs.getString("weightHistory","[]")),history=new org.json.JSONArray();for(int i=0;i<source.length();i++){org.json.JSONObject item=source.getJSONObject(i);String day=item.optString("date","");history.put(new org.json.JSONObject().put("weightKg",Double.parseDouble(item.getString("weight").replace(',','.'))).put("date",day.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}")?day:org.json.JSONObject.NULL));}return data.put("weightHistory",history);}
 public static String summary(Context c){String h=p(c).getString("height",""),w=p(c).getString("weight","");return activeLabel(c)+(h.isEmpty()?"":" · "+h+" cm")+(w.isEmpty()?"":" · "+w+" kg");}
 public static boolean owns(Context c,String key){String k="owner:"+key;int owner=owners(c).getInt(k,0);if(owner==0){owner=active(c);owners(c).edit().putInt(k,owner).apply();}return owner==active(c);}
 public static boolean belongs(Context c,String key){return owners(c).getInt("owner:"+key,active(c))==active(c);}
 public static String reportLine(Context c,String reportName){String n=reportName==null||reportName.trim().isEmpty()?name(c):reportName.trim();String h=p(c).getString("height",""),w=p(c).getString("weight",""),date=p(c).getString("weightDate","");return "Name: "+(n.isEmpty()?activeLabel(c):n)+" · Größe: "+(h.isEmpty()?"nicht angegeben":h+" cm")+" · Gewicht: "+(w.isEmpty()?"nicht angegeben":w+" kg"+(date.isEmpty()?"":" ("+displayDate(date)+")"));}
 private static String displayDate(String date){try{return LocalDate.parse(date).format(DateTimeFormatter.ofPattern("dd.MM.yyyy"));}catch(Exception e){return date;}}
 public static void select(Activity a,Runnable changed){String[] labels={slotName(a,1),slotName(a,2)};AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Aktiver Benutzer").setSingleChoiceItems(labels,active(a)-1,(d,w)->{if(!control(a).edit().putInt("active",w+1).commit()){Toast.makeText(a,"Benutzerwechsel fehlgeschlagen",1).show();return;}d.dismiss();Toast.makeText(a,labels[w]+" ist aktiv",0).show();if(changed!=null)changed.run();}).setNeutralButton("Profil bearbeiten",null).setNegativeButton("Schließen",null).create();dialog.setOnShowListener(v->dialog.getButton(-3).setOnClickListener(x->{dialog.dismiss();edit(a);}));dialog.show();}
 private static EditText field(Context c,String label,String value,int type,int max,LinearLayout box){TextView title=new TextView(c);title.setText(label);title.setTextSize(16);box.addView(title);EditText e=new EditText(c);e.setHint(label);e.setContentDescription(label);e.setText(value);e.setSingleLine(true);e.setInputType(type);e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(max)});box.addView(e);return e;}
 private static void history(Activity a,int n){try{JSONArray values=new JSONArray(slot(a,n).getString("weightHistory","[]"));StringBuilder text=new StringBuilder();for(int i=values.length()-1;i>=0;i--){JSONObject item=values.getJSONObject(i);text.append(displayDate(item.optString("date","Datum unbekannt"))).append(" · ").append(item.getString("weight")).append(" kg\n");}String old=slot(a,n).getString("weight","");if(values.length()==0&&!old.isEmpty())text.append("Bisheriger Eintrag: ").append(old).append(" kg (ohne Datum)");if(text.length()==0)text.append("Noch keine Gewichtsangaben gespeichert.");TextView body=new TextView(a);body.setText(text.toString());body.setTextSize(18);body.setPadding(24,16,24,16);ScrollView scroll=new ScrollView(a);scroll.addView(body);new AlertDialog.Builder(a).setTitle("Gewichtsverlauf · "+slotName(a,n)).setView(scroll).setPositiveButton("Schließen",null).show();}catch(Exception e){Toast.makeText(a,"Gewichtsverlauf konnte nicht gelesen werden",1).show();}}
 public static void edit(Activity a){final int n=active(a);final android.content.SharedPreferences prefs=slot(a,n);LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(28,14,28,16);TextView info=new TextView(a);info.setText("Profil für "+slotName(a,n)+"\nGröße und Gewicht sind freiwillig. Jeder Benutzer hat eigene Angaben.");info.setTextSize(16);box.addView(info);EditText name=field(a,"Name",prefs.getString("name",""),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_WORDS,40,box);EditText height=field(a,"Größe in cm (optional)",prefs.getString("height",""),InputType.TYPE_CLASS_NUMBER,3,box);EditText weight=field(a,"Gewicht in kg (optional)",prefs.getString("weight",""),InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL,6,box);final LocalDate[] date={LocalDate.now()};try{date[0]=LocalDate.parse(prefs.getString("weightDate",LocalDate.now().toString()));}catch(Exception ignored){}Button day=new Button(a);day.setAllCaps(false);Runnable dateLabel=()->day.setText("Gewicht vom: "+displayDate(date[0].toString()));dateLabel.run();day.setOnClickListener(v->{DatePickerDialog picker=new DatePickerDialog(a,(view,y,m,d)->{date[0]=LocalDate.of(y,m+1,d);dateLabel.run();},date[0].getYear(),date[0].getMonthValue()-1,date[0].getDayOfMonth());picker.getDatePicker().setMaxDate(System.currentTimeMillis());picker.show();});box.addView(day);Button today=new Button(a);today.setText("Heute gewogen");today.setAllCaps(false);today.setOnClickListener(v->{date[0]=LocalDate.now();dateLabel.run();weight.requestFocus();});box.addView(today);Button past=new Button(a);past.setText("Gewichtsverlauf ansehen");past.setAllCaps(false);past.setOnClickListener(v->history(a,n));box.addView(past);ScrollView scroll=new ScrollView(a);scroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Profil bearbeiten").setView(scroll).setNegativeButton("Abbrechen",null).setPositiveButton("Speichern",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(x->{try{String nm=name.getText().toString().trim(),h=height.getText().toString().trim(),w=weight.getText().toString().trim().replace(',','.');if(!h.isEmpty()){int cm=Integer.parseInt(h);if(cm<50||cm>250){height.setError("Bitte 50 bis 250 cm eingeben");return;}}if(!w.isEmpty()){double kg=Double.parseDouble(w);if(!Double.isFinite(kg)||kg<20||kg>400){weight.setError("Bitte 20 bis 400 kg eingeben");return;}w=String.format(Locale.GERMANY,"%.1f",kg);}if(!w.isEmpty()&&date[0].isAfter(LocalDate.now())){Toast.makeText(a,"Bitte ein Datum bis heute wählen",1).show();return;}String old=prefs.getString("weight",""),oldDate=prefs.getString("weightDate","");JSONArray values=new JSONArray(prefs.getString("weightHistory","[]"));if(values.length()==0&&!old.isEmpty())values.put(new JSONObject().put("weight",old).put("date",oldDate.isEmpty()?"Datum unbekannt":oldDate));boolean changed=!w.isEmpty()&&(!w.equals(old)||!date[0].toString().equals(oldDate));if(changed)values.put(new JSONObject().put("weight",w).put("date",date[0].toString()));android.content.SharedPreferences.Editor editor=prefs.edit().putString("name",nm).putString("height",h).putString("weight",w).putString("weightHistory",values.toString());if(w.isEmpty())editor.remove("weightDate");else editor.putString("weightDate",date[0].toString());if(!editor.commit()){Toast.makeText(a,"Profil konnte nicht gespeichert werden",1).show();return;}dialog.dismiss();Toast.makeText(a,"Profil gespeichert",0).show();a.recreate();}catch(NumberFormatException e){Toast.makeText(a,"Bitte gültige Größe und Gewicht eingeben",1).show();}catch(Exception e){Toast.makeText(a,"Profil konnte nicht gespeichert werden. Angaben bleiben erhalten.",1).show();}}));dialog.show();}
}
